import { cn } from '@cascivo/core/pure'
import { builtin, t } from '@cascivo/i18n'
import type { HTMLAttributes, ReactNode } from 'react'
import { Spinner } from '../spinner/spinner'
import styles from './inline-loading.module.css'

export type InlineLoadingStatus = 'inactive' | 'active' | 'finished' | 'error'

export interface InlineLoadingProps extends HTMLAttributes<HTMLDivElement> {
  status: InlineLoadingStatus
  label?: ReactNode
  labels?: {
    active?: string
    finished?: string
    error?: string
  }
}

function defaultLabel(status: InlineLoadingStatus, labels?: InlineLoadingProps['labels']): string {
  switch (status) {
    case 'active':
      return labels?.active ?? t(builtin.inlineLoading.active)
    case 'finished':
      return labels?.finished ?? t(builtin.inlineLoading.finished)
    case 'error':
      return labels?.error ?? t(builtin.inlineLoading.error)
    default:
      return ''
  }
}

function StatusIcon({ status }: { status: InlineLoadingStatus }) {
  if (status === 'active') {
    return <Spinner size="sm" className={styles['spinner']} />
  }
  if (status === 'finished') {
    return (
      <svg
        className={styles['icon']}
        viewBox="0 0 16 16"
        width="16"
        height="16"
        fill="none"
        aria-hidden="true"
      >
        <path
          d="M3.5 8.5l3 3 6-7"
          stroke="currentColor"
          strokeWidth="1.75"
          strokeLinecap="round"
          strokeLinejoin="round"
        />
      </svg>
    )
  }
  if (status === 'error') {
    return (
      <svg
        className={styles['icon']}
        viewBox="0 0 16 16"
        width="16"
        height="16"
        fill="none"
        aria-hidden="true"
      >
        <path
          d="M8 4.5v4M8 11h.01"
          stroke="currentColor"
          strokeWidth="1.75"
          strokeLinecap="round"
          strokeLinejoin="round"
        />
        <circle cx="8" cy="8" r="6.25" stroke="currentColor" strokeWidth="1.5" />
      </svg>
    )
  }
  return null
}

export function InlineLoading({ status, label, labels, className, ...props }: InlineLoadingProps) {
  const resolvedLabel = label ?? defaultLabel(status, labels)

  return (
    <div
      role="status"
      aria-live="polite"
      data-status={status}
      className={cn(styles['inline-loading'], className as string | undefined)}
      {...props}
    >
      <span className={styles['indicator']} aria-hidden="true">
        <StatusIcon status={status} />
      </span>
      {resolvedLabel && <span className={styles['label']}>{resolvedLabel}</span>}
    </div>
  )
}

@layer cascivo.component {
  .inline-loading {
    display: inline-flex;
    align-items: center;
    gap: var(--cascivo-space-2);
    font-family: var(--cascivo-font-sans);
    font-size: var(--cascivo-text-sm);
    line-height: var(--cascivo-leading-none);
    color: var(--cascivo-color-text);

    &[data-status='finished'] {
      color: var(--cascivo-color-success-foreground, var(--cascivo-color-success));
    }

    &[data-status='error'] {
      color: var(--cascivo-color-destructive);
    }
  }

  .indicator {
    display: inline-flex;
    flex-shrink: 0;
    align-items: center;
    justify-content: center;
    inline-size: 1rem;
    block-size: 1rem;
  }

  .spinner {
    color: var(--cascivo-color-text-muted);
  }

  .icon {
    inline-size: 1rem;
    block-size: 1rem;
    opacity: 1;

    /* Enter: fade the swapped-in result icon from the browser's first render */
    @starting-style {
      opacity: 0;
    }

    transition: opacity var(--cascivo-motion-enter);
  }

  .label {
    color: inherit;
  }
}

@media (forced-colors: active) {
  .inline-loading[data-status='finished'],
  .inline-loading[data-status='error'] {
    color: CanvasText;
  }
}

import type { ComponentMeta } from '@cascivo/core'

export const meta: ComponentMeta = {
  name: 'InlineLoading',
  description:
    'Compact inline status indicator that pairs a label with a loading, success, or error state',
  category: 'feedback',
  clientJs: 'none',
  states: ['inactive', 'active', 'finished', 'error'],
  variants: [],
  sizes: [],
  props: [
    {
      name: 'status',
      description: 'Status state.',
      type: "'inactive' | 'active' | 'finished' | 'error'",
      required: true,
    },
    {
      name: 'label',
      nameVisibility: 'visible',
      description: 'Text label for the control.',
      type: 'ReactNode',
      required: false,
    },
    {
      name: 'labels',
      description: 'Overrides for the component’s user-visible strings (i18n).',
      type: '{ active?: string; finished?: string; error?: string }',
      required: false,
    },
  ],
  tokens: [
    '--cascivo-color-text',
    '--cascivo-color-text-muted',
    '--cascivo-color-success',
    '--cascivo-color-destructive',
    '--cascivo-motion-enter',
  ],
  accessibility: {
    role: 'status',
    wcag: '2.2-AA',
    keyboard: [],
    reducedMotion: true,
    forcedColors: true,
  },
  examples: [
    { title: 'Active', code: '<InlineLoading status="active" />' },
    { title: 'Finished', code: '<InlineLoading status="finished" label="Saved" />' },
    { title: 'Error', code: '<InlineLoading status="error" label="Save failed" />' },
  ],
  dependencies: ['@cascivo/core', '@cascivo/i18n'],
  registryDependencies: ['spinner'],
  tags: ['loading', 'status', 'progress', 'feedback', 'spinner'],
  intent: {
    whenToUse: [
      'Showing the progress of a single inline action — a Save button that becomes "Saving… / Saved / Failed"',
      'Communicating async status next to a control without occupying its own block or modal',
      'Reflecting a terminal success or error state that should be announced to assistive tech',
    ],
    whenNotToUse: [
      'Page- or section-level loading where layout space is reserved — use Skeleton or Spinner',
      'Persistent, multi-line messages with recovery actions — use Alert or Notification',
      'Determinate progress with a known percentage — use a progress bar',
    ],
    antiPatterns: [
      {
        bad: '<Spinner /> with separate manually-managed success and error markup',
        good: '<InlineLoading status={status} /> driving icon and color from one status prop',
        why: 'A single status keeps the icon, color, and announced label in sync and prevents mismatched states',
      },
    ],
    related: [
      {
        name: 'Spinner',
        relationship: 'contains',
        reason:
          'InlineLoading renders a Spinner for its active state and adds finished/error icons plus a label',
      },
      {
        name: 'Alert',
        relationship: 'alternative',
        reason:
          'Use Alert for persistent messages that need a title, body, and actions rather than a terse status',
      },
    ],
    a11yRationale:
      'role="status" with aria-live="polite" announces the label when the status changes; the icon is decorative (aria-hidden) so meaning is carried by the text and color is never the sole signal',
    content: {
      tone: 'Terse and present-tense — "Saving", "Saved", "Save failed"',
      notes: 'Keep labels to a few words; the inactive status renders no label by default',
    },
    flexibility: [
      {
        area: 'label',
        level: 'flexible',
        note: 'Defaults come from the i18n catalog per status; override with label or the per-status labels map',
      },
      {
        area: 'status semantics',
        level: 'strict',
        note: 'active must show a spinner, finished a success icon, error an error icon — do not repurpose',
      },
    ],
  },
}
